/// Handles for every StarterKit extension, from [Engine.starterKit].
final class StarterKitHandles {
  StarterKitHandles._(EngineBuilder builder)
    : paragraph = builder.paragraph,
      blockquote = builder.add(Extensions.blockquote),
      bold = builder.add(Extensions.bold),
      bulletList = builder.add(Extensions.bulletList),
      code = builder.add(Extensions.code),
      codeBlock = builder.add(Extensions.codeBlock),
      hardBreak = builder.add(Extensions.hardBreak),
      heading = builder.add(Extensions.heading),
      history = builder.add(Extensions.history),
      horizontalRule = builder.add(Extensions.horizontalRule),
      italic = builder.add(Extensions.italic),
      link = builder.add(Extensions.link),
      listItem = builder.add(Extensions.listItem),
      orderedList = builder.add(Extensions.orderedList),
      strike = builder.add(Extensions.strike),
      taskList = builder.add(Extensions.taskList),
      trailingNode = builder.add(Extensions.trailingNode),
      underline = builder.add(Extensions.underline);

  /// Paragraphs.
  final ParagraphHandle paragraph;

  /// `blockquote`.
  final BlockquoteHandle blockquote;

  /// `bold`.
